#' Tabu Search on the Current Pareto Front
#'
#' @param instance Edge-list \code{data.frame}.
#' @param pareto_pop Integer matrix \code{[k x (n - 2)]}.
#' @param num_obj Integer.
#' @param n Integer.
#' @param neighbour_frac Numeric.
#' @param pop_size Integer.
#' @param lookup Optional lookup.
#' @param verbose Logical.
#' @return data.frame of non-dominated chromosomes.
#' @export
tabu_search <- function(instance, pareto_pop, num_obj, n,
                        neighbour_frac = 0.05, pop_size,
                        lookup = NULL, verbose = FALSE) {

  genes <- n - 2L
  pareto_pop <- as.matrix(pareto_pop)

  if (nrow(pareto_pop) > pop_size) pareto_pop <- pareto_pop[seq_len(pop_size), seq_len(genes), drop = FALSE]
  else                              pareto_pop <- pareto_pop[, seq_len(genes), drop = FALSE]

  pareto_pop <- unique(pareto_pop)
  if (nrow(pareto_pop) <= 1L) {
    if (verbose) message(" ... Tabu Search skipped: a single solution ...")
    return(as.data.frame(pareto_pop))
  }

  num_neighbours <- max(1L, ceiling(neighbour_frac * n))
  if (num_neighbours > nrow(pareto_pop)) num_neighbours <- nrow(pareto_pop)

  best_neighbours <- list()

  for (s in seq_len(nrow(pareto_pop))) {

    tabu <- matrix(integer(0L), ncol = genes)
    neighbourhood <- vector("list", num_neighbours)
    base <- pareto_pop[s, ]

    for (i in seq_len(num_neighbours)) {
      pos  <- sample.int(genes, 1L)
      newv <- sample.int(n, 1L)
      child <- base
      child[pos] <- newv

      if (!.row_in_matrix(child, tabu)) {
        neighbourhood[[i]] <- child
      }
    }

    neighbourhood <- do.call(rbind, neighbourhood)
    if (is.null(neighbourhood) || nrow(neighbourhood) == 0L) next

    neighbourhood <- rbind(neighbourhood, base)
    neighbourhood <- unique(neighbourhood)

    tabu <- rbind(tabu, neighbourhood)
    if (nrow(tabu) > pop_size) tabu <- tabu[seq_len(pop_size), , drop = FALSE]
    tabu <- unique(tabu)

    if (nrow(neighbourhood) > 1L) {
      ev <- compute_objectives(instance, neighbourhood, num_obj, lookup)
      ev <- non_dominated_crowding(ev, num_obj)
      ev <- ev[ev[, "rankingIndex"] == 1L, , drop = FALSE]
      best_neighbours[[length(best_neighbours) + 1L]] <-
        ev[, seq_len(genes), drop = FALSE]
    } else {
      best_neighbours[[length(best_neighbours) + 1L]] <- neighbourhood
    }
  }

  if (length(best_neighbours) == 0L) return(as.data.frame(pareto_pop))

  best <- do.call(rbind, best_neighbours)
  if (nrow(best) > 1L) {
    ev <- compute_objectives(instance, best, num_obj, lookup)
    ev <- non_dominated_crowding(ev, num_obj)
    ev <- ev[ev[, "rankingIndex"] == 1L, , drop = FALSE]
    out <- unique(ev[, seq_len(genes), drop = FALSE])
    return(as.data.frame(out))
  }
  as.data.frame(pareto_pop)
}


#' Path Relinking on the Current Pareto Front
#'
#' @inheritParams tabu_search
#' @return data.frame of non-dominated chromosomes.
#' @export
path_relinking <- function(instance, pareto_pop, num_obj, n, pop_size,
                           lookup = NULL, verbose = FALSE) {

  genes <- n - 2L
  pareto_pop <- as.matrix(pareto_pop)

  if (nrow(pareto_pop) > pop_size) pareto_pop <- pareto_pop[seq_len(pop_size), seq_len(genes), drop = FALSE]
  else                              pareto_pop <- pareto_pop[, seq_len(genes), drop = FALSE]
  pareto_pop <- unique(pareto_pop)

  if (nrow(pareto_pop) <= 1L) {
    if (verbose) message(" ... Path Relinking skipped: a single solution ...")
    return(as.data.frame(pareto_pop))
  }

  if (nrow(pareto_pop) == 2L) {
    pairs <- rbind(c(1L, 2L), c(2L, 1L))
  } else {
    pn <- t(utils::combn(nrow(pareto_pop), 2L))
    pairs <- rbind(pn, pn[, 2:1])
  }

  path_solutions <- list()
  path_seen <- list()

  for (p in seq_len(nrow(pairs))) {
    s_init  <- as.integer(pareto_pop[pairs[p, 1L], ])
    s_guide <- as.integer(pareto_pop[pairs[p, 2L], ])

    while (!identical(s_init, s_guide)) {
      diff_idx <- which(s_init != s_guide)
      if (length(diff_idx) == 0L) break

      intermediates <- matrix(rep(s_init, length(diff_idx)),
                              nrow = length(diff_idx),
                              byrow = TRUE)
      intermediates[cbind(seq_along(diff_idx), diff_idx)] <- s_guide[diff_idx]
      intermediates <- unique(intermediates)

      if (nrow(intermediates) > 1L) {
        ev <- compute_objectives(instance, intermediates, num_obj, lookup)
        ev <- non_dominated_crowding(ev, num_obj)
        best <- as.integer(ev[1L, seq_len(genes)])

        key <- paste(best, collapse = "_")
        if (!is.null(path_seen[[key]])) break

        path_solutions[[length(path_solutions) + 1L]] <- best
        path_seen[[key]] <- TRUE
        s_init <- best
      } else {
        s_init <- as.integer(intermediates[1L, ])
      }
    }
  }

  if (length(path_solutions) > 0L) {
    paths <- do.call(rbind, path_solutions)
    combined <- rbind(pareto_pop, paths)
  } else {
    combined <- pareto_pop
  }
  combined <- unique(combined)

  ev <- compute_objectives(instance, combined, num_obj, lookup)
  ev <- non_dominated_crowding(ev, num_obj)
  ev <- ev[ev[, "rankingIndex"] == 1L, , drop = FALSE]
  out <- unique(ev[, seq_len(genes), drop = FALSE])
  as.data.frame(out)
}


#' Pareto Local Search
#'
#' @inheritParams tabu_search
#' @return data.frame of chromosomes.
#' @export
pareto_local_search <- function(instance, pareto_pop, num_obj, n,
                                neighbour_frac = 0.10, pop_size,
                                lookup = NULL, verbose = FALSE) {

  genes <- n - 2L
  pareto_pop <- as.matrix(pareto_pop)

  if (nrow(pareto_pop) > pop_size) pareto_pop <- pareto_pop[seq_len(pop_size), seq_len(genes), drop = FALSE]
  else                              pareto_pop <- pareto_pop[, seq_len(genes), drop = FALSE]
  archive_chr <- unique(pareto_pop)

  if (nrow(archive_chr) <= 1L) {
    if (verbose) message(" ... PLS skipped: a single solution ...")
    return(as.data.frame(archive_chr))
  }

  key_of <- function(r) paste(as.integer(r), collapse = "_")
  explored_set <- new.env(hash = TRUE, parent = emptyenv())

  num_neighbours <- max(1L, ceiling(neighbour_frac * n))
  if (num_neighbours > nrow(archive_chr)) num_neighbours <- nrow(archive_chr)

  max_outer <- 5L * nrow(archive_chr) + 50L
  outer_iter <- 0L

  repeat {
    outer_iter <- outer_iter + 1L
    if (outer_iter > max_outer) break

    archive_keys <- apply(archive_chr, 1L, key_of)
    unexplored <- which(vapply(archive_keys,
                               function(k) is.null(explored_set[[k]]),
                               logical(1L)))
    if (length(unexplored) == 0L) break

    s_idx <- unexplored[sample.int(length(unexplored), 1L)]
    s_row <- archive_chr[s_idx, ]
    s_key <- archive_keys[s_idx]
    pos <- sample.int(genes, 1L)

    for (i in seq_len(num_neighbours)) {
      newv <- sample.int(n, 1L)
      sprime <- s_row
      sprime[pos] <- newv

      combined <- unique(rbind(sprime, archive_chr))
      if (nrow(combined) <= 1L) next

      ev <- compute_objectives(instance, combined, num_obj, lookup)
      ev <- non_dominated_crowding(ev, num_obj)
      nd_chr <- ev[ev[, "rankingIndex"] == 1L, seq_len(genes), drop = FALSE]
      nd_chr <- unique(nd_chr)
      if (.row_in_matrix(sprime, nd_chr)) {
        archive_chr <- nd_chr
      }
    }

    explored_set[[s_key]] <- TRUE
  }

  as.data.frame(archive_chr)
}


#' Apply the Configured Local-Search Variant
#'
#' @param instance Edge-list \code{data.frame}.
#' @param pareto_pop Integer matrix.
#' @param num_obj Integer.
#' @param n Integer.
#' @param variant One of \code{"base"}, \code{"PR"}, \code{"PLS"}, \code{"TS"}.
#' @param pop_size Integer.
#' @param lookup Optional lookup.
#' @param verbose Logical.
#' @return data.frame.
#' @export
apply_local_search <- function(instance, pareto_pop, num_obj, n, variant,
                               pop_size, lookup = NULL, verbose = FALSE) {

  variant <- match.arg(variant, c("base", "PR", "PLS", "TS"))
  switch(variant,
    base = as.data.frame(pareto_pop),
    PR   = path_relinking(instance, pareto_pop, num_obj, n, pop_size, lookup, verbose),
    PLS  = pareto_local_search(instance, pareto_pop, num_obj, n, 0.10, pop_size, lookup, verbose),
    TS   = tabu_search(instance, pareto_pop, num_obj, n, 0.05, pop_size, lookup, verbose)
  )
}


.row_in_matrix <- function(r, m) {
  if (is.null(m) || nrow(m) == 0L) return(FALSE)
  any(rowSums(abs(sweep(m, 2L, r, FUN = "-"))) == 0)
}

fast_non_dominated_sort <- function(obj_matrix) {

  obj_matrix <- as.matrix(obj_matrix)
  N <- nrow(obj_matrix)
  if (N == 0L) return(list())
  if (N == 1L) return(list(1L))

  dominated_count <- integer(N)
  dominates       <- vector("list", N)
  for (i in seq_len(N)) dominates[[i]] <- integer(0L)

  for (i in seq_len(N - 1L)) {
    oi <- obj_matrix[i, ]
    for (j in (i + 1L):N) {
      oj <- obj_matrix[j, ]
      diff <- oi - oj
      le_ij <- !any(diff > 0)
      lt_ij <- any(diff < 0)
      le_ji <- !any(diff < 0)
      lt_ji <- any(diff > 0)

      if (le_ij && lt_ij) {
        dominates[[i]] <- c(dominates[[i]], j)
        dominated_count[j] <- dominated_count[j] + 1L
      } else if (le_ji && lt_ji) {
        dominates[[j]] <- c(dominates[[j]], i)
        dominated_count[i] <- dominated_count[i] + 1L
      }
    }
  }

  fronts <- list()
  k <- 1L
  current <- which(dominated_count == 0L)
  while (length(current) > 0L) {
    fronts[[k]] <- current
    next_front <- integer(0L)
    for (i in current) {
      for (j in dominates[[i]]) {
        dominated_count[j] <- dominated_count[j] - 1L
        if (dominated_count[j] == 0L) next_front <- c(next_front, j)
      }
    }
    current <- next_front
    k <- k + 1L
  }
  fronts
}


crowding_distance_per_front <- function(obj_matrix, fronts, ranges) {

  N <- nrow(obj_matrix)
  M <- ncol(obj_matrix)
  cd <- matrix(0, nrow = N, ncol = M)

  for (front in fronts) {
    lf <- length(front)
    if (lf == 0L) next
    if (lf <= 2L) {
      cd[front, ] <- Inf
      next
    }
    for (m in seq_len(M)) {
      ord <- front[order(obj_matrix[front, m])]
      cd[ord[1L], m] <- Inf
      cd[ord[lf], m] <- Inf
      r <- ranges[m]
      if (is.finite(r) && r > 0) {
        inner <- 2L:(lf - 1L)
        cd[ord[inner], m] <-
          (obj_matrix[ord[inner + 1L], m] - obj_matrix[ord[inner - 1L], m]) / r
      }
    }
  }
  cd
}


#' Assign Pareto Rank and Crowding Distance
#'
#' @param population Numeric matrix \code{[N x (vars + num_obj)]}.
#' @param num_obj Integer.
#' @return Matrix with extra columns \code{rankingIndex} and \code{density}.
#' @export
non_dominated_crowding <- function(population, num_obj) {

  population <- as.matrix(population)
  pop_size <- nrow(population)
  total_cols <- ncol(population)
  var_no <- total_cols - num_obj

  obj_cols <- (var_no + 1L):total_cols
  obj <- population[, obj_cols, drop = FALSE]

  fronts <- fast_non_dominated_sort(obj)

  ranking_index <- integer(pop_size)
  for (i in seq_along(fronts)) ranking_index[fronts[[i]]] <- i

  ranges <- apply(obj, 2L, function(x) max(x) - min(x))
  cd <- crowding_distance_per_front(obj, fronts, ranges)
  density <- rowSums(cd)

  result <- cbind(population, rankingIndex = ranking_index, density = density)
  ord <- order(ranking_index, -density)
  result[ord, , drop = FALSE]
}


#' Tournament Selection
#'
#' @param population Matrix with last two columns being \code{rankingIndex}
#'   and \code{density}.
#' @param pop_size Integer.
#' @param tour_size Integer.
#' @return Selected subpopulation matrix.
#' @export
tournament_selection <- function(population, pop_size, tour_size) {

  population <- as.matrix(population)
  nc <- ncol(population)
  N <- nrow(population)
  rank_col <- nc - 1L
  dens_col <- nc

  ranks <- population[, rank_col]
  dens  <- population[, dens_col]

  tournaments <- matrix(sample.int(N, pop_size * tour_size, replace = TRUE),
                        nrow = pop_size, ncol = tour_size)
  winners <- apply(tournaments, 1L, function(idx) {
    o <- order(ranks[idx], -dens[idx])
    idx[o[1L]]
  })
  population[winners, , drop = FALSE]
}

/* momst explorer: paleta institucional UTM (verde y amarillo, minimalista).
   Tokens y escala tipográfica tomados de la hoja de estilos de referencia. */
:root {
  --bg: #f7f8f5; --superficie: #ffffff; --superficie2: #f0f2ec; --borde: #e1e5db;
  --texto: #17220f; --texto2: #55604a; --texto3: #98a18d;
  --g1: #1e6b14; --g2: #2e8a1f; --g3: #4aab30; --g4: #72c255; --g6: #e2f2da;
  --y3: #d4a80a; --y6: #fdf3cc;
  --rojo: #b3261e;
  --r: 12px;
  --sombra: 0 1px 3px rgba(20, 40, 10, .06), 0 4px 18px rgba(20, 40, 10, .05);
  --fs-micro: 10.5px; --fs-xs: 11.5px; --fs-sm: 12.5px; --fs-md: 13.5px;
  --fs-base: 14px; --fs-lg: 16px; --fs-xl: 19px; --fs-2xl: 22px; --fs-3xl: 26px;

  --bs-body-font-family: 'Inter', system-ui, sans-serif;
  --bs-body-font-size: var(--fs-base);
  --bs-body-color: var(--texto);
  --bs-body-bg: var(--bg);
  --bs-border-color: var(--borde);
  --bs-link-color: var(--g1);
  --bs-link-color-rgb: 30, 107, 20;
  --bs-link-hover-color: var(--g2);
  --bs-primary: var(--g1);
  --bs-primary-rgb: 30, 107, 20;
}

body { font-family: 'Inter', system-ui, sans-serif; background: var(--bg); color: var(--texto);
  font-size: var(--fs-base); }
a { color: var(--g1); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---- franja institucional ---- */
.franja-utm { height: 4px; border-radius: 99px; margin-bottom: 18px;
  background: linear-gradient(90deg, var(--g1) 0 72%, var(--y3) 72% 100%); }

/* ---- barra lateral ---- */
.bslib-sidebar-layout > .sidebar { background: var(--superficie) !important;
  border-right: 1px solid var(--borde) !important; }
.bslib-sidebar-layout > .sidebar > .sidebar-content { padding: 0 0 14px; gap: 0; }
.bslib-sidebar-layout { --bslib-sidebar-main-bg: var(--bg); --_border: var(--borde); }
.sidebar-logo { padding: 18px 16px 14px; border-bottom: 1px solid var(--borde); }
.sidebar-logo img { width: 100%; max-width: 210px; height: auto; display: block; margin-bottom: 12px; }
.sidebar-logo h1 { font-family: 'Playfair Display', serif; font-size: var(--fs-lg); color: var(--g1);
  line-height: 1.3; margin: 0; font-weight: 700; }
.sidebar-logo p { font-size: var(--fs-xs); color: var(--texto3); margin: 3px 0 0; }
.seccion-nav { font-size: var(--fs-micro); font-weight: 600; letter-spacing: .1em; text-transform: uppercase;
  color: var(--texto3); padding: 16px 16px 6px; }
.sidebar-acciones { padding: 14px 16px 0; display: grid; gap: 10px; }
.sidebar-pie { margin-top: 16px; padding: 14px 16px 0; border-top: 1px solid var(--borde);
  font-size: var(--fs-micro); color: var(--texto3); line-height: 1.6; }

/* acordeón de parámetros con aspecto de secciones de navegación */
.sidebar .accordion { --bs-accordion-border-color: var(--borde); --bs-accordion-bg: var(--superficie);
  --bs-accordion-border-radius: 0; --bs-accordion-inner-border-radius: 0;
  --bs-accordion-active-bg: var(--g6); --bs-accordion-active-color: var(--g1);
  --bs-accordion-btn-focus-box-shadow: none; border-radius: 0; }
.bslib-sidebar-layout > .sidebar > .sidebar-content { overflow-x: hidden; }
.bslib-sidebar-layout > .sidebar .accordion { margin-left: 0 !important; margin-right: 0 !important;
  width: 100%; }
.sidebar .accordion-item { border-left: 0; border-right: 0; }
.sidebar .accordion-item:first-of-type { border-top: 0; }
.sidebar .accordion-button { font-size: var(--fs-micro); font-weight: 600; letter-spacing: .1em;
  text-transform: uppercase; color: var(--texto3); padding: 12px 16px; }
.sidebar .accordion-button:not(.collapsed) { color: var(--g1); box-shadow: none; }
.sidebar .accordion-body { padding: 12px 16px 6px; }

/* ---- encabezado de página ---- */
.encabezado { margin-bottom: 18px; }
.titulo-pagina { font-size: var(--fs-2xl); font-weight: 700; margin: 0 0 4px; color: var(--texto); }
.subtitulo-pagina { color: var(--texto2); font-size: var(--fs-md); margin: 0; max-width: 820px; }
code { color: var(--g1); background: var(--g6); border-radius: 5px; padding: 1px 5px; font-size: .92em; }

/* ---- tarjetas e indicadores ---- */
.cuadricula { display: grid; gap: 14px; }
.kpis { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); margin-bottom: 18px; }
.tarjeta, .card { background: var(--superficie); border: 1px solid var(--borde) !important;
  border-radius: var(--r) !important; box-shadow: var(--sombra); }
.tarjeta { padding: 16px 18px; }
.kpi-valor { font-size: var(--fs-3xl); font-weight: 700; color: var(--g1); line-height: 1.15;
  font-variant-numeric: tabular-nums; }
.kpi-valor small { font-size: var(--fs-md); font-weight: 600; color: var(--texto2); margin-left: 4px; }
.kpi-etiqueta { font-size: var(--fs-xs); font-weight: 600; text-transform: uppercase; letter-spacing: .07em;
  color: var(--texto3); margin-top: 4px; display: flex; align-items: center; gap: 7px; }
.kpi-nota { font-size: var(--fs-xs); color: var(--texto2); margin-top: 2px; }
.kpi-instancia .kpi-valor { color: var(--texto); }
.punto { width: 9px; height: 9px; border-radius: 50%; display: inline-block; flex-shrink: 0; }
.titulo-tarjeta { font-size: var(--fs-xs); font-weight: 600; text-transform: uppercase; letter-spacing: .08em;
  color: var(--texto3); margin-bottom: 12px; }
.titulo-grafico { font-size: var(--fs-md); font-weight: 600; color: var(--texto); margin-bottom: 6px; }

/* ---- pestañas ---- */
.card-header { background: var(--superficie); border-bottom: 2px solid var(--borde); padding: 6px 14px 0; }
.nav-underline { --bs-nav-underline-gap: 4px; --bs-nav-underline-border-width: 2px;
  --bs-nav-underline-link-active-color: var(--g1); }
.nav-underline .nav-link { padding: 9px 12px; font-size: var(--fs-md); font-weight: 600; color: var(--texto3);
  margin-bottom: -2px; }
.nav-link:hover, .accordion-button:hover { text-decoration: none; }
.nav-underline .nav-link:hover { color: var(--texto2); border-bottom-color: var(--borde); }
.nav-underline .nav-link.active { color: var(--g1); border-bottom-color: var(--g1); font-weight: 600; }
.card-body { padding: 18px; }

/* ---- controles ---- */
.form-label, .control-label, .shiny-input-container > label { font-size: var(--fs-sm); font-weight: 600;
  color: var(--texto2); margin-bottom: 5px; }
.shiny-input-container { margin-bottom: 12px; width: 100% !important; }
.form-control, .form-select, .selectize-input { min-height: 36px; padding: 6px 11px; border: 1px solid var(--borde);
  border-radius: 8px; font-size: var(--fs-md); font-family: inherit; background: var(--superficie2);
  color: var(--texto); box-shadow: none; }
.form-control:focus, .form-select:focus, .selectize-input.focus { border-color: var(--g2); background: #fff;
  box-shadow: none; }
.selectize-dropdown { font-size: var(--fs-md); border-color: var(--borde); }
.selectize-dropdown .active { background: var(--g6); color: var(--g1); }
.form-check { font-size: var(--fs-md); color: var(--texto); }
.form-check-input { border-color: var(--texto3); }
.form-check-input:checked { background-color: var(--g1); border-color: var(--g1); }
.form-check-input:focus { border-color: var(--g2); box-shadow: 0 0 0 .2rem rgba(46, 138, 31, .18); }
.form-text, .help-block { font-size: var(--fs-xs); color: var(--texto3); }
.input-group .btn { border-radius: 8px 0 0 8px; }

.btn { border-radius: 8px; font-size: var(--fs-md); font-weight: 600; padding: 8px 16px;
  transition: background .13s; }
.btn-primary { --bs-btn-bg: var(--g1); --bs-btn-border-color: var(--g1); --bs-btn-hover-bg: var(--g2);
  --bs-btn-hover-border-color: var(--g2); --bs-btn-active-bg: var(--g1); --bs-btn-active-border-color: var(--g1);
  --bs-btn-disabled-bg: var(--g4); --bs-btn-disabled-border-color: var(--g4); --bs-btn-color: #fff;
  --bs-btn-hover-color: #fff; --bs-btn-active-color: #fff; background: var(--g1); color: #fff; }
.btn-primary:hover, .btn-primary:focus { background: var(--g2); border-color: var(--g2); color: #fff; }
.btn-default:not(.btn-primary), .btn-secondary, .btn-outline-secondary { background: var(--superficie2); color: var(--texto2);
  border: 1px solid var(--borde); }
.btn-default:not(.btn-primary):hover, .btn-secondary:hover, .btn-outline-secondary:hover { background: var(--g6); color: var(--g1);
  border-color: var(--borde); }
.btn-sm, .boton-pequeno { padding: 4px 10px; font-size: var(--fs-sm); }

/* deslizadores */
.irs--shiny .irs-bar { background: var(--g2); border-top-color: var(--g2); border-bottom-color: var(--g2); }
.irs--shiny .irs-line { background: var(--superficie2); border-color: var(--borde); }
.irs--shiny .irs-handle { border-color: var(--g1); }
.irs--shiny .irs-single, .irs--shiny .irs-from, .irs--shiny .irs-to { background: var(--g1);
  font-family: inherit; font-size: var(--fs-micro); }
.irs--shiny .irs-min, .irs--shiny .irs-max { background: var(--superficie2); color: var(--texto3);
  font-size: var(--fs-micro); }
.irs--shiny .irs-grid-text { color: var(--texto3); }

/* ---- tablas ---- */
.tabla-envoltura { max-width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; }
.shiny-table, table.tabla { width: 100%; border-collapse: collapse; font-size: var(--fs-md);
  --bs-table-bg: transparent; --bs-table-hover-bg: var(--superficie2); margin-bottom: 0; }
.shiny-table th { text-align: left; padding: 9px 10px !important; font-size: var(--fs-micro);
  text-transform: uppercase; letter-spacing: .06em; color: var(--texto3); font-weight: 600;
  border-bottom: 2px solid var(--borde) !important; white-space: nowrap; }
.shiny-table td { padding: 8px 10px !important; border-bottom: 1px solid var(--borde);
  font-variant-numeric: tabular-nums; color: var(--texto); }
.shiny-table tr:hover td { background: var(--superficie2); }
.shiny-table td[align="right"] { white-space: nowrap; }

/* ---- avisos ---- */
.aviso { background: var(--y6); border: 1px solid #ecd9a0; color: #8a6500; border-radius: 8px;
  padding: 9px 12px; font-size: var(--fs-sm); line-height: 1.45; }
.vacio { text-align: center; color: var(--texto3); padding: 48px 20px; font-size: var(--fs-md); }
.vacio strong { display: block; color: var(--texto2); font-size: var(--fs-lg); margin-bottom: 6px; }
.shiny-output-error-validation { color: var(--texto3); font-size: var(--fs-md); padding: 40px 0; text-align: center; }
.barra-acciones { display: flex; flex-wrap: wrap; gap: 9px; align-items: flex-end; margin-bottom: 14px; }
.barra-acciones .shiny-input-container { margin-bottom: 0; width: 240px !important; }
.barra-acciones .btn { height: 36px; display: inline-flex; align-items: center; gap: 6px; }
.registro pre, pre.shiny-text-output { background: var(--superficie2); border: 1px solid var(--borde);
  border-radius: 8px; color: var(--texto2); font-size: var(--fs-sm); max-height: 520px; }

/* notificaciones y progreso con aspecto de toasts */
#shiny-notification-panel { right: 18px; bottom: 18px; max-width: 360px; }
.shiny-notification { background: var(--superficie); border: 1px solid var(--borde); border-left: 4px solid var(--g2);
  border-radius: 11px; box-shadow: 0 10px 30px rgba(0, 0, 0, .14); color: var(--texto);
  font-size: var(--fs-md); opacity: 1; }
.shiny-notification-error { border-left-color: var(--rojo); }
.shiny-notification-warning { border-left-color: var(--y3); }
.shiny-notification .progress { height: 10px; background: var(--superficie2); border: 1px solid var(--borde);
  border-radius: 99px; }
.shiny-notification .progress-bar { background: linear-gradient(90deg, var(--g2), var(--g3)); border-radius: 99px; }
.shiny-progress-notification .progress-message { font-weight: 600; }
.shiny-progress-notification .progress-detail { color: var(--texto2); }

/* contenido de la pestaña "Acerca de" */
.acerca { max-width: 760px; font-size: var(--fs-base); line-height: 1.6; color: var(--texto); }
.acerca h3 { font-size: var(--fs-lg); font-weight: 700; margin: 18px 0 8px; }
.acerca table { width: auto; border-collapse: collapse; font-size: var(--fs-md); margin: 6px 0 14px; }
.acerca th { font-size: var(--fs-micro); text-transform: uppercase; letter-spacing: .06em; color: var(--texto3);
  border-bottom: 2px solid var(--borde); padding: 7px 12px 7px 0; text-align: left; }
.acerca td { border-bottom: 1px solid var(--borde); padding: 7px 12px 7px 0; }
.acerca code { color: var(--g1); background: var(--g6); border-radius: 5px; padding: 1px 5px; }
.acerca pre { background: var(--superficie2); border: 1px solid var(--borde); border-radius: 8px; padding: 12px; }
.acerca pre code { background: none; color: var(--texto); padding: 0; }

/* foco visible por teclado */
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible,
.nav-link:focus-visible { outline: 2px solid var(--g2); outline-offset: 2px; border-radius: 6px; }

/* sin desbordes */
.bslib-page-main, .card, .tarjeta { max-width: 100%; min-width: 0; }
.shiny-plot-output img { max-width: 100%; }

@media (max-width: 640px) {
  .form-control, .form-select, .selectize-input, input, select { font-size: var(--fs-lg); }
  .kpis { grid-template-columns: repeat(2, 1fr); gap: 10px; }
  .kpi-valor { font-size: var(--fs-2xl); }
  .kpi-etiqueta { font-size: var(--fs-micro); }
  .titulo-pagina { font-size: var(--fs-xl); }
  .subtitulo-pagina { font-size: var(--fs-sm); }
  .card-body { padding: 14px; }
  .nav-underline { flex-wrap: nowrap; overflow-x: auto; }
  .nav-underline .nav-link { white-space: nowrap; font-size: var(--fs-sm); }
  .barra-acciones .shiny-input-container { width: 100% !important; }
  .shiny-table th, .shiny-table td { padding: 8px !important; }
}
@media (max-width: 380px) { .kpis { grid-template-columns: 1fr; } }
